import { Component, Input, inject } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { ROUTES_PATH_TOKENS } from 'src/app/app.routes';
import { Pie } from 'src/app/models/pie';
import { CartService } from 'src/app/services/cart.service';
import { PieService } from 'src/app/services/pie.service';

@Component({
  standalone: true,
  imports: [
    MatButtonModule,
  ],
  selector: 'app-card',
  templateUrl: './card.component.html',
  styleUrls: ['./card.component.css']
})
export class CardComponent {
  @Input() pie!: Pie;
  readonly cartService = inject(CartService);
  readonly pieService = inject(PieService);
  readonly router = inject(Router);
  readonly activatedRoute = inject(ActivatedRoute);

  selectPie(pie: Pie) {
    this.pieService.setSelectedPie(pie.id);
    this.router.navigate([`../${ROUTES_PATH_TOKENS.SHOP}`], { relativeTo: this.activatedRoute });
  }
}
<div class="pie-item">
  <button
  ><img [src]="pie.image" alt="Delicious Apple Pie" /></button>
  <div class="quantity-selector">
    <button (click)="cartService.decrementCartItem(pie)">-</button>
    <span (click)="cartService.addCartItem(pie)">{{ pie.quantity ? pie.quantity + ' in Cart' : 'Add to Cart'}}</span>
    <button (click)="cartService.addCartItem(pie)">+</button>
  </div>
  <div class="pie-info">
    <div>
      <h4>{{ pie.title }}</h4>
    </div>
    <div>
      <p>{{ pie.price }}</p>
    </div>
  </div>
</div>
